<?php require_once __DIR__.'/../includes/functions.php';$items=[];try{$items=db()->query("SELECT b.*,c.name category FROM businesses b LEFT JOIN business_categories c ON c.id=b.category_id WHERE b.status='approved' ORDER BY b.business_name")->fetchAll();}catch(Throwable $e){}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business Directory | Plateau Digital</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><?php include __DIR__.'/../includes/public_header.php';?><main class="section page-section"><span class="eyebrow">Discover local businesses</span><h1>Plateau Business Directory</h1><p>Find businesses, products and services across Plateau State.</p><p><a class="btn" href="register_business.php">List your business</a></p><div class="business-grid"><?php if(!$items):?><div class="empty-state">No approved listings yet. The directory is preparing for its first businesses.</div><?php else:foreach($items as $b):?><article class="business-card"><span class="badge"><?=e($b['category']??'Business')?></span><h3><?=e($b['business_name'])?></h3><p><?=e($b['description'])?></p><small><?=e($b['city'])?>, <?=e($b['state'])?></small></article><?php endforeach;endif;?></div></main><?php include __DIR__.'/../includes/public_footer.php';?></body></html>